import{_ as a}from"./chunks/academic-pmbench-four-boundary-intention-runtime.DFrSqv-N.js";import{_ as n,C as r,o as i,c as s,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"A Deferred Intention Is Not a Memory Entry","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"A Deferred Intention Is Not a Memory Entry","date":"2026-09-02","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"What runtime architecture is required when an agent must execute the latest valid deferred intention at the correct future cue rather than merely recall it?","summary":"PM-Bench separates remembering an instruction from acting when it is actually due. Its results suggest that more monitoring alone is not enough; a long-running agent needs versioned intention state, an observation policy, due-state admission and durable effect evidence.","sources":"arXiv:2607.12385; genglinliu/PMBench @ e1093c470c8981daf522d4ef047a7c3a71e077d7; research/reading/A-20260902-01-pmbench-prospective-memory.md; research/analysis/A-20260902-01-pmbench-prospective-memory.md","cover":"/assets/covers/academic-pmbench-versioned-intention-runtime.png"},"headers":[],"relativePath":"en/digital-employee/2026-09-02-pmbench-versioned-intention-runtime.md","filePath":"en/digital-employee/2026-09-02-pmbench-versioned-intention-runtime.md","lastUpdated":1788366540000}'),c={name:"en/digital-employee/2026-09-02-pmbench-versioned-intention-runtime.md"};function d(h,e,p,u,m,g){const t=r("ArticleCover");return i(),s("div",null,[o(t,{image:"/assets/covers/academic-pmbench-versioned-intention-runtime.png",kicker:"Digital Employee · Academic Observation 006",title:"A Deferred Intention Is Not a Memory Entry",summary:"Remembering a future task is not the same as having authority to execute it now.",version:"DE006",status:"Academic Runtime V5 · 2026-09-02",languageHref:"/zh/digital-employee/2026-09-02-pmbench-versioned-intention-runtime",languageLabel:"中文"}),e[0]||(e[0]=l('<h1 id="a-deferred-intention-is-not-a-memory-entry" tabindex="-1">A Deferred Intention Is Not a Memory Entry <a class="header-anchor" href="#a-deferred-intention-is-not-a-memory-entry" aria-label="Permalink to &quot;A Deferred Intention Is Not a Memory Entry&quot;">​</a></h1><p>A user says: “When the shipment arrives, send the confirmation.”</p><p>A long-context agent may remember this sentence perfectly for days. It can quote it back, explain what it means and keep it in a todo list. Yet none of those facts prove that the agent will do the right thing when the shipment actually arrives.</p><p>It can still fail in several ways. It may never check shipment status. It may send the confirmation before arrival. It may miss a reschedule. It may execute an instruction that was cancelled yesterday. Or it may retry after a network timeout and send the same confirmation twice.</p><p>Those are not all retrieval failures.</p><p><strong>PM-Bench: Evaluating Prospective Memory in LLM Agents</strong>, introduced by Genglin Liu and Saadia Gabriel, makes this distinction measurable. Instead of asking only whether an agent can recall past information, PM-Bench asks whether it can carry a deferred intention through ongoing activity and execute it at the correct future time or environmental cue. The arXiv record was submitted on July 14, 2026 and lists the work as a COLM 2026 conference paper.</p><p>The narrower finding is already useful: <strong>prospective memory is a separate agent capability from retrospective recall.</strong> The engineering consequence we derive is stronger, and must be labeled as our own: a deferred intention should be a versioned runtime object whose future authority is evaluated against current evidence, not merely a string stored in memory.</p><h2 id="pm-bench-tests-remember-to-act-not-just-remember" tabindex="-1">PM-Bench tests “remember to act,” not just “remember” <a class="header-anchor" href="#pm-bench-tests-remember-to-act-not-just-remember" aria-label="Permalink to &quot;PM-Bench tests “remember to act,” not just “remember”&quot;">​</a></h2><p>The benchmark simulates a seven-day week with 80 steps. The paper reports 83 task definitions, 81 scored executable tasks, including event-based and time-based tasks, regular and one-off tasks, cross-day tasks, and 11 updates covering cancellation, override and rescheduling.</p><p>The environment exposes channels such as clock, email, calendar, course portal, price tracker, bank balance, shipment status, laundry status, library hold, reservation waitlist and appointment portal. Some deferred intentions therefore cannot become actionable until the agent checks the relevant state.</p><p>That structure creates a distinction that production runtimes also need:</p><p><strong>active does not mean due.</strong></p><p>A task can be a valid future obligation and still provide zero authority to act at the current moment. PM-Bench formalizes a due set at each step: the currently valid tasks whose execution conditions are satisfied now.</p><p>This sounds simple. It is one of the most important boundaries in long-running agent design.</p><h2 id="a-bigger-memory-can-preserve-the-wrong-intention-perfectly" tabindex="-1">A bigger memory can preserve the wrong intention perfectly <a class="header-anchor" href="#a-bigger-memory-can-preserve-the-wrong-intention-perfectly" aria-label="Permalink to &quot;A bigger memory can preserve the wrong intention perfectly&quot;">​</a></h2><p>Prospective-memory failures are especially dangerous when the instruction changes.</p><p>Suppose the user first says “renew the reservation Friday morning,” then later reschedules it to Friday afternoon. A memory system that keeps both messages has succeeded at retention. A runtime that still treats the old version as executable has failed at authority.</p><p>Cancellation is even clearer. The old intention should remain in history because the system may need to explain what happened. But historical persistence must not imply current execution authority.</p><p>PM-Bench includes cancellation, override and rescheduling cases precisely because prospective behavior depends on maintaining the current intention, not simply retaining more text.</p><p>This gives us a useful rule:</p><blockquote><p><strong>History should be appendable; authority should be versioned.</strong></p></blockquote><p>The old instruction can remain visible for audit. Only the latest valid version may become due.</p><h2 id="more-heartbeat-is-not-the-same-as-more-reliability" tabindex="-1">More heartbeat is not the same as more reliability <a class="header-anchor" href="#more-heartbeat-is-not-the-same-as-more-reliability" aria-label="Permalink to &quot;More heartbeat is not the same as more reliability&quot;">​</a></h2><p>PM-Bench evaluates eight agent configurations across eight model backbones. These include a single-agent baseline, todo ledger, optional heartbeat, automatic heartbeats, a hierarchical specialist design and replay-based ensembles.</p><p>The paper&#39;s aggregate results are important because they resist a tempting shortcut.</p><p>The optional-heartbeat configuration reports the highest aggregate macro F1, <strong>65.1</strong>. A 30-minute automatic heartbeat performs more queries but reports <strong>489 false positives</strong> and a lower aggregate macro F1 of <strong>57.8</strong>. The hierarchical union-query setup performs <strong>1,661 queries</strong> yet reports aggregate macro F1 of <strong>45.2</strong>.</p><p>These are author-reported benchmark results; this Academic run did not independently reproduce them. They do not prove that fewer checks are always better. They support a narrower point: <strong>polling more often is not a substitute for deciding what to observe, when to observe it and what evidence is sufficient to act.</strong></p><p>A digital employee that checks every connector every few minutes may look vigilant while wasting tokens, tool calls and provider quota. Worse, every observation creates another opportunity for premature or duplicate action if admission is weak.</p><p>Monitoring therefore needs its own policy.</p><h2 id="no-scaffold-wins-for-every-model" tabindex="-1">No scaffold wins for every model <a class="header-anchor" href="#no-scaffold-wins-for-every-model" aria-label="Permalink to &quot;No scaffold wins for every model&quot;">​</a></h2><p>The paper also reports different best configurations for different backbones. Optional heartbeat is strongest for some tested models; a plain single-agent baseline is strongest for others; a todo ledger or automatic heartbeat wins elsewhere.</p><p>That variation matters. It means we should not turn “prospective memory” into one universal prompt wrapper.</p><p>A good runtime can instead externalize the stable part of the problem — intention identity, version, observation, due-state proof and effect evidence — while still allowing different models to use different reasoning strategies inside that boundary.</p><p>The model can remain intelligent. The future authority should become inspectable.</p><h2 id="cross-day-and-update-sensitive-tasks-expose-the-lifecycle" tabindex="-1">Cross-day and update-sensitive tasks expose the lifecycle <a class="header-anchor" href="#cross-day-and-update-sensitive-tasks-expose-the-lifecycle" aria-label="Permalink to &quot;Cross-day and update-sensitive tasks expose the lifecycle&quot;">​</a></h2><p>PM-Bench reports that no tested setup exceeds 50% on both cross-day and update-sensitive task performance. Its strongest aggregate cross-day result is 50.0%; its strongest update-sensitive result is 47.2%.</p><p>Again, these are source-reported figures, not independent reproduction. But the two categories reveal different failure mechanisms.</p><p>A cross-day task asks whether an intention survives intervening activity. An update-sensitive task asks whether the system can retire stale authority after cancellation, override or rescheduling.</p><p>The first looks like memory persistence. The second is unmistakably lifecycle control.</p><p>A system can therefore be excellent at remembering and still be unsafe at acting.</p><h2 id="a-four-boundary-prospective-intention-runtime" tabindex="-1">A four-boundary prospective-intention runtime <a class="header-anchor" href="#a-four-boundary-prospective-intention-runtime" aria-label="Permalink to &quot;A four-boundary prospective-intention runtime&quot;">​</a></h2><p>The following architecture is a <strong>Research Center synthesis</strong> inspired by PM-Bench. It is not an architecture proposed or validated by the paper.</p><p><img src="'+a+`" alt="Four-boundary prospective-intention runtime: intention state, observation policy, due/action admission and effect evidence."></p><h3 id="_1-versioned-intention-state" tabindex="-1">1. Versioned Intention State <a class="header-anchor" href="#_1-versioned-intention-state" aria-label="Permalink to &quot;1. Versioned Intention State&quot;">​</a></h3><p>A deferred intention should have a durable identity and version, not only natural-language text.</p><p>At minimum, keep its current status, trigger, timezone, dependencies, target and supersession history. Cancellation should close authority. Rescheduling should create or advance a version. Completion should be durable.</p><p>The important asymmetry is deliberate: <strong>old versions remain auditable but cannot become executable again just because the model recalls them.</strong></p><h3 id="_2-observation-policy" tabindex="-1">2. Observation Policy <a class="header-anchor" href="#_2-observation-policy" aria-label="Permalink to &quot;2. Observation Policy&quot;">​</a></h3><p>The runtime must know what evidence can make the intention due.</p><p>A calendar event can be event-driven. A shipment may require provider notification or polling. A price threshold may require a fresh market observation. A human reply may arrive through an inbox webhook.</p><p>Each trigger therefore needs an observation policy: source, cadence or subscription, freshness, cost and evidence identity.</p><p>This is where the PM-Bench monitoring results become useful. The right question is not “how often should the model wake up?” but “what evidence is required to decide this intention, and what is the cheapest reliable way to obtain it?”</p><h3 id="_3-due-action-admission" tabindex="-1">3. Due / Action Admission <a class="header-anchor" href="#_3-due-action-admission" aria-label="Permalink to &quot;3. Due / Action Admission&quot;">​</a></h3><p>Before any side effect, check the current intention against current evidence.</p><p>A minimal rule looks like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>latest_version</span></span>
<span class="line"><span>AND status == active</span></span>
<span class="line"><span>AND trigger == satisfied_now</span></span>
<span class="line"><span>AND dependencies == satisfied</span></span>
<span class="line"><span>AND effect_not_already_committed</span></span>
<span class="line"><span>=&gt; action_admitted</span></span></code></pre></div><p>This boundary prevents a common semantic collapse: active future work becoming present permission.</p><p>The model may help interpret ambiguous language, but the runtime should still bind the resulting interpretation to a version and an evidence snapshot before granting authority.</p><h3 id="_4-effect-evidence" tabindex="-1">4. Effect Evidence <a class="header-anchor" href="#_4-effect-evidence" aria-label="Permalink to &quot;4. Effect Evidence&quot;">​</a></h3><p>The system must record what actually happened externally.</p><p>An effect receipt can bind the intention ID and version, the admission evidence, the action identity, provider response and completion state. This is not part of PM-Bench&#39;s synthetic evaluation; it is an additional production requirement.</p><p>Why add it? Because prospective execution and recovery meet at exactly this boundary. If an API call succeeds but the agent crashes before seeing the response, “remembering the intention” on restart can cause a duplicate side effect. The runtime needs provider-effect evidence to decide whether retry is safe.</p><h2 id="a-todo-list-helps-but-it-is-not-the-whole-contract" tabindex="-1">A todo list helps, but it is not the whole contract <a class="header-anchor" href="#a-todo-list-helps-but-it-is-not-the-whole-contract" aria-label="Permalink to &quot;A todo list helps, but it is not the whole contract&quot;">​</a></h2><p>PM-Bench reports that a todo ledger improves aggregate performance relative to the single baseline. That is useful evidence that explicit task state can help.</p><p>But a todo item normally answers “what should I remember?” A production intention record must also answer:</p><ul><li>which version is current;</li><li>which observation proves the trigger;</li><li>whether the action is due now;</li><li>whether dependencies are satisfied;</li><li>whether the external effect already occurred.</li></ul><p>That difference is why prospective memory belongs partly in the model and partly in the runtime.</p><h2 id="what-pm-bench-supports-—-and-what-it-does-not" tabindex="-1">What PM-Bench supports — and what it does not <a class="header-anchor" href="#what-pm-bench-supports-—-and-what-it-does-not" aria-label="Permalink to &quot;What PM-Bench supports — and what it does not&quot;">​</a></h2><p>The paper and its official repository provide primary evidence for several bounded claims:</p><ul><li>prospective memory can be evaluated separately from retrospective recall;</li><li>delayed tasks with hidden triggers, cross-day persistence and updates remain difficult for the tested agents;</li><li>no single scaffold dominates all evaluated model backbones;</li><li>more monitoring queries do not automatically produce the best aggregate outcome.</li></ul><p>They do <strong>not</strong> establish:</p><ul><li>that our four-boundary runtime is the uniquely correct architecture;</li><li>exactly-once semantics for real external providers;</li><li>that PM-Bench scores predict enterprise safety;</li><li>that a particular heartbeat cadence is universally optimal;</li><li>independent reproduction of the source-reported headline results.</li></ul><p>The paper and <code>genglinliu/PMBench</code> repository are the same primary research family. This run found no independent full reproduction. COLM publication is publication evidence, not correctness proof.</p><h2 id="the-operational-rule" tabindex="-1">The operational rule <a class="header-anchor" href="#the-operational-rule" aria-label="Permalink to &quot;The operational rule&quot;">​</a></h2><p>A long-running digital employee should not treat “I remember the instruction” as permission to act.</p><p>The safer structure is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory          -&gt; helps the model recall</span></span>
<span class="line"><span>intention state -&gt; identifies the latest valid future obligation</span></span>
<span class="line"><span>observation     -&gt; proves the current trigger state</span></span>
<span class="line"><span>due admission   -&gt; grants authority for this moment</span></span>
<span class="line"><span>effect evidence -&gt; proves what happened externally</span></span></code></pre></div><p>This makes prospective behavior inspectable. When the agent misses a task, we can ask whether it lost the intention, failed to observe the trigger, mis-evaluated due state or failed at execution. When it acts incorrectly, we can ask whether it used a stale version, admitted too early or replayed an already-completed effect.</p><p>That is a better failure model than saying simply, “the agent forgot.”</p><h2 id="what-remains-open" tabindex="-1">What remains open <a class="header-anchor" href="#what-remains-open" aria-label="Permalink to &quot;What remains open&quot;">​</a></h2><p>PM-Bench creates a controlled testbed, but production systems still need answers to harder questions. How should observation budget be scheduled across thousands of deferred intentions? Which triggers should use events rather than polling? How should schedule materializations be invalidated after rescheduling? What provider evidence is sufficient to prevent duplicate effects after ambiguous timeouts? How should a runtime separate a model-memory failure from a scheduler or connector failure?</p><p>Those questions point to the next evaluation step: not a larger memory benchmark, but a runtime benchmark that injects cancellation, rescheduling, delayed provider acknowledgements, crashes and retries.</p><p>Until then, the practical conclusion is bounded but strong: <strong>a deferred intention is not merely something an agent should remember. It is future authority, and future authority needs a lifecycle.</strong></p><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ol><li>Genglin Liu and Saadia Gabriel, <strong>PM-Bench: Evaluating Prospective Memory in LLM Agents</strong>, arXiv:2607.12385, 2026-07-14 — <a href="https://arxiv.org/abs/2607.12385" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.12385</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2607.12385" target="_blank" rel="noreferrer">https://arxiv.org/html/2607.12385</a></li><li>Official repository <strong>genglinliu/PMBench</strong>, inspected at <code>e1093c470c8981daf522d4ef047a7c3a71e077d7</code> — <a href="https://github.com/genglinliu/PMBench" target="_blank" rel="noreferrer">https://github.com/genglinliu/PMBench</a></li><li>Governed Deep Reading — <code>research/reading/A-20260902-01-pmbench-prospective-memory.md</code></li><li>Governed Research Analysis — <code>research/analysis/A-20260902-01-pmbench-prospective-memory.md</code></li></ol><p><strong>Evidence boundary:</strong> Items 1–3 are primary/first-party research artifacts. Numerical results are source-reported and were not independently reproduced in this run. The four-boundary prospective-intention runtime is explicitly Research Center synthesis rather than a PM-Bench author claim.</p>`,86))])}const v=n(c,[["render",d]]);export{y as __pageData,v as default};
